class LRUCache:
    """固定容量的 LRU 缓存,基于哈希表 + 双向链表,get/put 均为 O(1)。"""

    class _Node:
        __slots__ = ("key", "value", "prev", "next")

        def __init__(self, key=None, value=None):
            self.key, self.value = key, value
            self.prev = self.next = None

    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._map = {}
        # 哨兵头尾节点,省去边界判断
        self._head, self._tail = self._Node(), self._Node()
        self._head.next, self._tail.prev = self._tail, self._head

    def _remove(self, node):
        node.prev.next, node.next.prev = node.next, node.prev

    def _push_front(self, node):
        node.next, node.prev = self._head.next, self._head
        self._head.next.prev = node
        self._head.next = node

    def get(self, key):
        node = self._map.get(key)
        if node is None:
            return None
        self._remove(node)
        self._push_front(node)
        return node.value

    def put(self, key, value):
        if key in self._map:
            self._remove(self._map[key])
        node = self._Node(key, value)
        self._map[key] = node
        self._push_front(node)
        if len(self._map) > self.capacity:
            lru = self._tail.prev
            self._remove(lru)
            del self._map[lru.key]

def binary_search(sorted_list, target):
    """在升序列表中二分查找 target,返回下标,不存在返回 -1。

    经典写法要点:
    - 闭区间 [lo, hi],循环条件 lo <= hi;
    - mid 用 lo + (hi - lo) // 2 防止大数溢出(其他语言中重要)。
    """
    lo, hi = 0, len(sorted_list) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if sorted_list[mid] == target:
            return mid
        elif sorted_list[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


assert binary_search([1, 3, 5, 7, 9], 7) == 3
assert binary_search([1, 3, 5, 7, 9], 4) == -1
assert binary_search([], 1) == -1

import functools
import logging
import random
import time


def retry(max_attempts=3, base_delay=1.0, max_delay=30.0, retry_on=(Exception,)):
    """指数退避 + 随机抖动的重试装饰器。

    delay = min(max_delay, base_delay * 2**attempt) * uniform(0.5, 1.5)
    """

    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            for attempt in range(max_attempts):
                try:
                    return fn(*args, **kwargs)
                except retry_on as exc:
                    if attempt == max_attempts - 1:
                        raise
                    delay = min(max_delay, base_delay * (2 ** attempt))
                    delay *= random.uniform(0.5, 1.5)
                    logging.warning(
                        "%s failed (attempt %d/%d): %s, retrying in %.1fs",
                        fn.__name__, attempt + 1, max_attempts, exc, delay,
                    )
                    time.sleep(delay)
        return wrapper

    return decorator

