def f(a, s, t):
    import heapq
    n = len(a)
    d = [1 << 60] * n
    d[s] = 0
    q = [(0, s)]
    while q:
        c, u = heapq.heappop(q)
        if c > d[u]:
            continue
        if u == t:
            return c
        for v, w in a[u]:
            x = c + w
            if x < d[v]:
                d[v] = x
                heapq.heappush(q, (x, v))
    return -1

def fizzbuzz(n):
    """经典 FizzBuzz:3 的倍数输出 Fizz,5 的倍数输出 Buzz,同时是则输出 FizzBuzz。"""
    result = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result


